import sys,difflib,re
L=open(sys.argv[1],encoding='utf8').read().split('\n')
minus=[];plus=[]
hn=0
for l in L:
    if l.startswith('@@'):
        hn+=1
    elif l.startswith('---') or l.startswith('+++'): pass
    elif l.startswith('-'): minus.append((hn,l[1:]))
    elif l.startswith('+'): plus.append((hn,l[1:]))
print(len(minus),len(plus))
for (h,a),(h2,b) in zip(minus,plus):
    ta=re.findall(r'\S+|\s+',a);tb=re.findall(r'\S+|\s+',b)
    sm=difflib.SequenceMatcher(None,ta,tb,autojunk=False)
    print('=== hunk',h, 'len',len(b))
    for op,i1,i2,j1,j2 in sm.get_opcodes():
        if op=='equal':
            continue
        ctx=''.join(tb[max(0,j1-12):j1])
        print(f'[{op}] ...{ctx[-120:]}\n   OLD: {"".join(ta[i1:i2])}\n   NEW: {"".join(tb[j1:j2])}')
EOF

